52	// xssUnsafeTypes contains MIME types that could execute scripts if served directly.
53	// These are served as application/octet-stream to prevent XSS attacks.
54	var xssUnsafeTypes = map[string]bool{
55		"text/html":                true,
56		"text/javascript":          true,
57		"application/javascript":   true,
58		"application/x-javascript": true,
59		"text/xml":                 true,
60		"application/xml":          true,
61		"application/xhtml+xml":    true,
62	}
63	
64	// thumbnailSupportedTypes contains image MIME types that support thumbnail generation.
65	var thumbnailSupportedTypes = map[string]bool{
66		"image/png":  true,
67		"image/jpeg": true,
68		"image/jpg":  true,
69		"image/heic": true,
70		"image/heif": true,
71		"image/webp": true,
72	}
73	
74	// avatarAllowedTypes contains MIME types allowed for user avatars.
75	var avatarAllowedTypes = map[string]bool{
76		"image/png":  true,
77		"image/jpeg": true,
78		"image/jpg":  true,
79		"image/gif":  true,
80		"image/webp": true,
81		"image/heic": true,
82		"image/heif": true,
83	}
84	
85	// SupportedThumbnailMimeTypes is the exported list of thumbnail-supported MIME types.
86	var SupportedThumbnailMimeTypes = []string{
87		"image/png",
88		"image/jpeg",
89		"image/jpg",
90		"image/heic",
91		"image/heif",
92		"image/webp",
93	}
94	
95	var errUseOriginalForThumbnail = errors.New("serve original image instead of metadata-stripping thumbnail")
96	
97	// dataURIRegex parses data URI format: data:image/png;base64,iVBORw0KGgo...
98	var dataURIRegex = regexp.MustCompile(`^data:(?P<type>[^;]+);base64,(?P<base64>.+)`)
